import os
import glob
import pandas as pd
import argparse

def merge_csv_files(target_dir):
    search_pattern = os.path.join(target_dir, "*_part*.csv")
    csv_files = glob.glob(search_pattern)
    
    if not csv_files:
        print("fail to find any csv files")
        return

    groups = {}
    for f in csv_files:
        prefix = f.split('_part')[0]
        if prefix not in groups:
            groups[prefix] = []
        groups[prefix].append(f)

    for prefix, files in groups.items():
        df_list =[pd.read_csv(f) for f in files]
        merged_df = pd.concat(df_list, ignore_index=True)
        
        final_csv = prefix + '.csv'
        merged_df.to_csv(final_csv, index=False)
        print(f"✅ merge {len(files)} shards -> final file: {os.path.basename(final_csv)}")
        
        for f in files: 
            os.remove(f)

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Merge sharded CSV files generated by multi-GPU evaluation.")
    parser.add_argument("--target_dir", type=str, required=True, help="Directory containing the sharded *_part*.csv files.")
    
    args = parser.parse_args()
    merge_csv_files(args.target_dir)